@code {
    private AppointmentModel Model { get; set; } = new();
    private bool _showStep2;
    private bool _validated;
    private bool _submitted;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();

    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(Model);
        _editContext.AddValidationMessages();

        // Validate step 1 fields manually
        var isValid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !Model.Email.Contains('@'))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            isValid = false;

        // Use DataAnnotationsValidator via EditForm's built-in validation
        // We trigger validation by checking if step 1 fields have values
        if (isValid)
        {
            _showStep2 = true;
            _serverErrors.Clear();
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        _validated = false;
        _serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _validated = false;

        if (string.IsNullOrEmpty(Model.Doctor) || !Model.AppointmentDate.HasValue
            || string.IsNullOrEmpty(Model.TimeSlot) || string.IsNullOrWhiteSpace(Model.Reason))
        {
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            _serverErrors = errors;
        }
        else
        {
            _validated = true;
        }
    }

    private void HandleSubmit()
    {
        if (_validated)
        {
            _submitted = true;
        }
    }
}
"}

